-- Attach operational triggers after the restored function closure.
-- Historical award capture/protection and CO numbering are intentionally not attached.
-- Those identities are governed by the canonical source commercial services.
set local search_path=pg_catalog,public,extensions;

do $trigger$ begin if not exists(select 1 from pg_trigger where tgrelid='public.company_documents'::regclass and tgname='carez_ticket_document_sync' and not tgisinternal) then execute $captured$CREATE TRIGGER carez_ticket_document_sync AFTER INSERT OR DELETE OR UPDATE ON company_documents FOR EACH ROW EXECUTE FUNCTION carez_ticket_document_sync_trigger();$captured$;end if;end $trigger$;
