-- Fail on conflicting historical duplicates; never merge or delete costs.
create unique index if not exists project_cost_vendor_bill_line_unique ON public.project_costs USING btree (vendor_bill_line_id) WHERE (vendor_bill_line_id IS NOT NULL);
